import type { AgentTeamClaim, AgentTeamMemberId, AgentTeamProjectRef, AgentTeamTask, AgentTeamTaskRef } from './types/entities.ts'

export const REVIEW_BACKLOG_IDLE_MS = 30 * 60 * 1000
export const STALLED_PUBLIC_MS = 24 * 60 * 60 * 1000
export const STALLED_IDLE_MS = 24 * 60 * 60 * 1000

export type ReminderKind = 'review-backlog' | 'stalled'

export interface ReminderClaimFacts {
  readonly claim: AgentTeamClaim
  readonly createdSequence: number
}

export interface ReminderTaskFacts {
  readonly task: AgentTeamTask
  readonly projectActive: boolean
  readonly statusBaselineSequence: number
  readonly statusBaselineOccurredAt: string
  readonly latestPublicSequence: number
  readonly latestPublicOccurredAt: string
  readonly claims: readonly ReminderClaimFacts[]
}

export interface ReminderEvaluationInput {
  readonly nowMs: number
  readonly tasks: readonly ReminderTaskFacts[]
  readonly isOwner: (projectRef: AgentTeamProjectRef, memberId: AgentTeamMemberId) => boolean
  readonly isAvailable: (memberId: AgentTeamMemberId) => boolean
  /** Milliseconds idle, or undefined when this Host has not observed a complete running → idle interval. */
  readonly idleMs: (memberId: AgentTeamMemberId) => number | undefined
  readonly heldEver: (taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId) => boolean
  readonly episodeExists: (taskRef: AgentTeamTaskRef, kind: ReminderKind, recipient: AgentTeamMemberId, baselineSequence: number) => boolean
  readonly hasUnreadResponsibility: (taskRef: AgentTeamTaskRef, recipient: AgentTeamMemberId) => boolean
}

export interface ReminderCandidate {
  readonly taskRef: AgentTeamTaskRef
  readonly kind: ReminderKind
  readonly recipient: AgentTeamMemberId
  readonly baselineSequence: number
}

function eligible(input: ReminderEvaluationInput, candidate: ReminderCandidate): boolean {
  return !input.episodeExists(candidate.taskRef, candidate.kind, candidate.recipient, candidate.baselineSequence)
    && !input.hasUnreadResponsibility(candidate.taskRef, candidate.recipient)
}

/** Evaluate every open Task once. Unknown runtime presence never becomes an idle duration. */
export function planTaskReminders(input: ReminderEvaluationInput): readonly ReminderCandidate[] {
  const candidates: ReminderCandidate[] = []
  for (const facts of input.tasks) {
    const { task } = facts
    if (!facts.projectActive || task.resolution !== 'open') continue
    if (task.status === 'in_review') {
      const recipient = task.accountable === 'member:human'
        || !input.isOwner(task.projectRef, task.accountable)
        || input.heldEver(task.taskRef, task.accountable)
        ? 'member:human' as AgentTeamMemberId : task.accountable
      const idleMs = input.idleMs(recipient)
      const ready = recipient === 'member:human'
        ? input.nowMs - Date.parse(facts.statusBaselineOccurredAt) >= REVIEW_BACKLOG_IDLE_MS
        : idleMs !== undefined && idleMs >= REVIEW_BACKLOG_IDLE_MS
      const candidate = { taskRef: task.taskRef, kind: 'review-backlog' as const, recipient, baselineSequence: facts.statusBaselineSequence }
      if (ready && input.isAvailable(recipient) && eligible(input, candidate)) candidates.push(candidate)
      continue
    }
    if (task.status !== 'in_progress') continue
    const activeClaims = facts.claims.filter(entry => entry.claim.state === 'active')
    const quiet = input.nowMs - Date.parse(facts.latestPublicOccurredAt) > STALLED_PUBLIC_MS
    const executorIdle = activeClaims.some(entry => {
      const idleMs = input.idleMs(entry.claim.owner)
      return idleMs !== undefined && idleMs > STALLED_IDLE_MS
    })
    const baselineSequence = Math.max(facts.latestPublicSequence, ...activeClaims.map(entry => entry.createdSequence))
    const candidate = { taskRef: task.taskRef, kind: 'stalled' as const, recipient: task.accountable, baselineSequence }
    if ((quiet || executorIdle) && input.isAvailable(task.accountable) && eligible(input, candidate)) candidates.push(candidate)
  }
  return candidates
}

import type { AgentTeamProjectRef, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types/entities.ts'
import type { AgentTeamInboxItem, AgentTeamInboxReminder, AgentTeamMainTimelineEntry } from './types/requests-results.ts'

/** Ordinary Thread updates an owner accumulates per Thread before they interrupt it; a runtime parameter, never stored. */
export const INBOX_THRESHOLD_UPDATES = 5

export type InboxDelivery = 'immediate' | 'threshold'

/** The reader's role in one notice scope, as the notice states it. */
export type InboxScopeRole = 'owner' | 'follower' | 'member'

export interface InboxThreadUnread {
  readonly item: AgentTeamInboxItem
  readonly facts: readonly AgentTeamThreadReadFact[]
  readonly reminders?: readonly AgentTeamInboxReminder[]
}

export interface InboxMainUnread {
  readonly projectRef: AgentTeamProjectRef
  readonly entries: readonly AgentTeamMainTimelineEntry[]
}

export interface InboxDeliveryInput {
  readonly threads: readonly InboxThreadUnread[]
  readonly main: readonly InboxMainUnread[]
  readonly owns: (projectRef: AgentTeamProjectRef) => boolean
  /** Newest ordinary sequence each Thread's threshold updates were last delivered through. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  /** Signature of the immediate facts the last delivery attempt answered. */
  readonly covered: string | undefined
}

export interface InboxThreadPlan {
  readonly threadRef: AgentTeamThreadRef
  readonly role: InboxScopeRole
  readonly delivery: InboxDelivery
  /** Ordinary facts that wait for the threshold; zero unless the reader owns the Project. */
  readonly thresholdCount: number
}

export interface InboxDeliveryPlan {
  /** Why a notice goes out now, or `undefined` when nothing may interrupt the reader. */
  readonly trigger: InboxDelivery | undefined
  readonly signature: string
  /** `summarizedThrough` as it stands once this plan's notice is delivered. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  readonly threads: readonly InboxThreadPlan[]
}

function isThresholdFact(entry: AgentTeamThreadReadFact, owner: boolean): boolean {
  return owner && entry.fact.kind === 'message' && !entry.direct
}

/**
 * Decide whether the reader's current unread interrupts it. Mentions, replies to the reader, activities, Main stream unread and
 * a non-owner follower's ordinary updates are immediate; an owner's ordinary Thread updates wait until one Thread holds
 * `INBOX_THRESHOLD_UPDATES` undelivered ones, and otherwise ride along with the next immediate notice.
 */
export function planInboxDelivery(input: InboxDeliveryInput): InboxDeliveryPlan {
  const immediate: (string | number)[][] = []
  const summarizedThrough = new Map<AgentTeamThreadRef, number>()
  const threads: InboxThreadPlan[] = []
  let thresholdReached = false
  for (const { item, facts, reminders = [] } of input.threads) {
    const threadRef = item.thread.threadRef
    if (reminders.length > 0) immediate.push([threadRef, 'reminder', ...reminders.map(reminder => `${reminder.kind}:${reminder.baselineSequence}`)])
    const owner = input.owns(item.projectRef)
    const waiting = facts.filter(entry => isThresholdFact(entry, owner))
    const now = facts.filter(entry => !isThresholdFact(entry, owner)).map(entry => entry.fact.sequence)
    if (now.length > 0) immediate.push([threadRef, ...now])
    const through = input.summarizedThrough.get(threadRef) ?? 0
    if (waiting.filter(entry => entry.fact.sequence > through).length >= INBOX_THRESHOLD_UPDATES) thresholdReached = true
    if (waiting.length > 0) summarizedThrough.set(threadRef, waiting.at(-1)!.fact.sequence)
    threads.push(Object.freeze({ threadRef, role: owner ? 'owner' : item.attention === undefined ? 'member' : 'follower',
      delivery: now.length > 0 || reminders.length > 0 ? 'immediate' : 'threshold', thresholdCount: waiting.length }))
  }
  for (const { projectRef, entries } of input.main) {
    if (entries.length > 0) immediate.push([projectRef, ...entries.map(entry => entry.sequence)])
  }
  const signature = immediate.length === 0 ? '' : JSON.stringify(immediate)
  const trigger = signature !== '' && signature !== input.covered ? 'immediate' : thresholdReached ? 'threshold' : undefined
  return Object.freeze({ trigger, signature, summarizedThrough, threads: Object.freeze(threads) })
}

