    taskRef: marker.taskRef, kind: marker.kind, recipient: marker.memberId, baselineSequence: marker.baselineSequence,
    sequence: marker.sequence, occurredAt: this.state.occurredAtBySequence.get(marker.sequence) ?? '',
  })))
}

