private issueConfirmation(
  actor: AgentTeamHumanActor | AgentTeamMemberActor,
  workspaceId: WorkspaceId,
  projectRef: AgentTeamProjectRef,
  body: string,
  recipients: readonly AgentTeamMemberId[],
  task?: AgentTeamTask,
  thread?: AgentTeamThread,
): AgentTeamConfirmationRequired {
  if (actor.kind !== 'human') throw new Error('only Human may invite an unfollowed Agent')
  for (const [token, confirmation] of this.confirmations) if (confirmation.actor === actor.memberId) this.confirmations.delete(token)
  const confirmationToken = `confirmation:${randomUUID()}` as AgentTeamConfirmationToken
  this.confirmations.set(confirmationToken, Object.freeze({ actor: actor.memberId, workspaceId, projectRef,
    ...(task === undefined ? {} : { taskRef: task.taskRef }), ...(thread === undefined ? {} : { threadRef: thread.threadRef }),
    body, recipients, attention: recipients.map(memberId => thread !== undefined && this.isFollowing(thread.threadRef, memberId)),
    memberStates: recipients.map(memberId => this.state.members.get(memberId)?.state ?? 'enabled') }))
  return Object.freeze({ kind: 'confirmation_required', confirmationToken, workspaceId, projectRef,
    recipients: Object.freeze(recipients.filter(memberId => this.state.members.has(memberId) && (thread === undefined || !this.isFollowing(thread.threadRef, memberId)))),
    ...(task === undefined ? {} : { taskRef: task.taskRef }), ...(thread === undefined ? {} : { threadRef: thread.threadRef, revision: thread.revision }) })
}

private consumeConfirmation(
  token: AgentTeamConfirmationToken,
  actor: AgentTeamHumanActor | AgentTeamMemberActor,
  workspaceId: WorkspaceId,
  projectRef: AgentTeamProjectRef,
  task: AgentTeamTask | undefined,
  thread: AgentTeamThread | undefined,
  body: string,
  recipients: readonly AgentTeamMemberId[],
): void {
  const confirmation = this.confirmations.get(token)
  this.confirmations.delete(token)
  const attention = recipients.map(memberId => thread !== undefined && this.isFollowing(thread.threadRef, memberId))
  const states = recipients.map(memberId => this.state.members.get(memberId)?.state ?? 'enabled')
  if (confirmation === undefined || confirmation.actor !== actor.memberId || confirmation.workspaceId !== workspaceId
    || confirmation.projectRef !== projectRef || confirmation.taskRef !== task?.taskRef || confirmation.threadRef !== thread?.threadRef
    || confirmation.body !== body || !this.sameList(confirmation.recipients, recipients)
    || !this.sameList(confirmation.attention, attention) || !this.sameList(confirmation.memberStates, states)) {
    throw new Error('confirmation token is invalid or expired')
  }
}

private assertMentionTargets(project: AgentTeamProject, recipients: readonly AgentTeamMemberId[]): void {
  for (const memberId of recipients) {
    if (memberId === AGENT_TEAM_HUMAN_MEMBER_ID) continue
    const member = this.requireMember(memberId)
    if (member.state === 'inactive' || member.state === 'archived' || !this.participatesIn(member.memberId, project.workspaceId)) {
      throw new Error(`Agent Member '${memberId}' is not authorized for Project '${project.projectRef}'`)
    }
  }
}

private requireRulesVersion2(what: string): void {
  if (this.state.rulesVersion < 2) throw new Error(`${what} needs rules version 2; this ledger runs version ${this.state.rulesVersion}`)
}

private requireProjectMemberActor(actor: AgentTeamHumanActor | AgentTeamMemberActor, projectRef: AgentTeamProjectRef): void {
  this.requireProjectMemberActorFrom(this.state, actor, projectRef)
}

private requireProjectMemberActorFrom(projection: Projection, actor: AgentTeamHumanActor | AgentTeamMemberActor, projectRef: AgentTeamProjectRef): void {
  if (actor.kind === 'member' && !this.isProjectMemberFrom(projection, projectRef, actor.memberId)) {
    throw new Error(`Agent Member '${actor.handle}' is not a member of Project '${projectRef}' (not_project_member) — ${recoveryFor('not_project_member').sentence({ projectRef })}`)
  }
}

private resolveAccountable(projectRef: AgentTeamProjectRef, actor: AgentTeamHumanActor | AgentTeamMemberActor, requested?: AgentTeamMemberId): AgentTeamMemberId {
  const accountable = requested ?? (actor.kind === 'member' ? actor.memberId : AGENT_TEAM_HUMAN_MEMBER_ID)
  if (accountable !== AGENT_TEAM_HUMAN_MEMBER_ID) {
    const member = this.requireMember(accountable)
    if (member.state !== 'enabled' || !this.isProjectOwnerFrom(this.state, projectRef, accountable)) {
      throw new Error(`Task accountable '${member.handle}' must be an enabled Project owner or the Human (accountable_target_invalid) — ${recoveryFor('accountable_target_invalid').sentence({})}`)
    }
  }
  return accountable
}

private validateTaskSources(projectRef: AgentTeamProjectRef, requested?: readonly AgentTeamThreadRef[]): readonly AgentTeamThreadRef[] {
  const sourceThreadRefs = Object.freeze([...new Set(requested ?? [])])
  if (sourceThreadRefs.length !== (requested?.length ?? 0)) throw new Error('sourceThreadRefs contains duplicate Threads')
  for (const threadRef of sourceThreadRefs) {
    const thread = this.state.threads.get(threadRef)
    if (thread === undefined || thread.taskRef !== undefined || this.projectRefForThreadFrom(this.state, threadRef) !== projectRef) {
      throw new Error(`source Thread '${threadRef}' must be a discussion in the Task's Project`)
    }
  }
  return sourceThreadRefs
}

private heldTaskClaimFrom(projection: Projection, taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId): boolean {
  return (projection.claimsByTask.get(taskRef) ?? []).some(claim => claim.owner === memberId)
}

private accountableIsValidFrom(projection: Projection, task: AgentTeamTask): boolean {
  return task.accountable === AGENT_TEAM_HUMAN_MEMBER_ID || this.isProjectOwnerFrom(projection, task.projectRef, task.accountable)
}

private responsibilityActivityRecipientsFrom(projection: Projection, task: AgentTeamTask, actor: AgentTeamMemberId): readonly AgentTeamMemberId[] {
  const recipients = new Set<AgentTeamMemberId>()
  if (task.status === 'in_review') {
    if (task.accountable === AGENT_TEAM_HUMAN_MEMBER_ID || !this.heldTaskClaimFrom(projection, task.taskRef, task.accountable)) recipients.add(task.accountable)
    else recipients.add(AGENT_TEAM_HUMAN_MEMBER_ID)
  } else if (task.status === 'todo') recipients.add(task.accountable)
  recipients.delete(actor)
  return [...recipients]
}

private mergeResponsibilityReturn(
  tasks: readonly AgentTeamTask[],
  threads: readonly AgentTeamThread[],
  returned: { readonly tasks: readonly AgentTeamTask[]; readonly threads: readonly AgentTeamThread[] },
): { readonly tasks: readonly AgentTeamTask[]; readonly threads: readonly AgentTeamThread[] } {
  const taskMap = new Map(tasks.map(task => [task.taskRef, task]))
  for (const task of returned.tasks) taskMap.set(task.taskRef, task)
  const threadMap = new Map(threads.map(thread => [thread.threadRef, thread]))
  for (const thread of returned.threads) threadMap.set(thread.threadRef, thread)
  return { tasks: [...taskMap.values()], threads: [...threadMap.values()] }
}

private accountabilityReturnsFrom(projection: Projection, memberId: AgentTeamMemberId, sequence: number,
  projectRefs?: ReadonlySet<AgentTeamProjectRef>): {
  readonly transfers: readonly AgentTeamTaskActivity[]
  readonly tasks: readonly AgentTeamTask[]
  readonly threads: readonly AgentTeamThread[]
  readonly markers: readonly AgentTeamActivityMarker[]

import type { AgentTeamProjectRef, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types/entities.ts'
import type { AgentTeamInboxItem, AgentTeamInboxReminder, AgentTeamMainTimelineEntry } from './types/requests-results.ts'

/** Ordinary Thread updates an owner accumulates per Thread before they interrupt it; a runtime parameter, never stored. */
export const INBOX_THRESHOLD_UPDATES = 5

export type InboxDelivery = 'immediate' | 'threshold'

/** The reader's role in one notice scope, as the notice states it. */
export type InboxScopeRole = 'owner' | 'follower' | 'member'

export interface InboxThreadUnread {
  readonly item: AgentTeamInboxItem
  readonly facts: readonly AgentTeamThreadReadFact[]
  readonly reminders?: readonly AgentTeamInboxReminder[]
}

export interface InboxMainUnread {
  readonly projectRef: AgentTeamProjectRef
  readonly entries: readonly AgentTeamMainTimelineEntry[]
}

export interface InboxDeliveryInput {
  readonly threads: readonly InboxThreadUnread[]
  readonly main: readonly InboxMainUnread[]
  readonly owns: (projectRef: AgentTeamProjectRef) => boolean
  /** Newest ordinary sequence each Thread's threshold updates were last delivered through. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  /** Signature of the immediate facts the last delivery attempt answered. */
  readonly covered: string | undefined
}

export interface InboxThreadPlan {
  readonly threadRef: AgentTeamThreadRef
  readonly role: InboxScopeRole
  readonly delivery: InboxDelivery
  /** Ordinary facts that wait for the threshold; zero unless the reader owns the Project. */
  readonly thresholdCount: number
}

export interface InboxDeliveryPlan {
  /** Why a notice goes out now, or `undefined` when nothing may interrupt the reader. */
  readonly trigger: InboxDelivery | undefined
  readonly signature: string
  /** `summarizedThrough` as it stands once this plan's notice is delivered. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  readonly threads: readonly InboxThreadPlan[]
}

function isThresholdFact(entry: AgentTeamThreadReadFact, owner: boolean): boolean {
  return owner && entry.fact.kind === 'message' && !entry.direct
}

/**
 * Decide whether the reader's current unread interrupts it. Mentions, replies to the reader, activities, Main stream unread and
 * a non-owner follower's ordinary updates are immediate; an owner's ordinary Thread updates wait until one Thread holds
 * `INBOX_THRESHOLD_UPDATES` undelivered ones, and otherwise ride along with the next immediate notice.
 */
export function planInboxDelivery(input: InboxDeliveryInput): InboxDeliveryPlan {
  const immediate: (string | number)[][] = []
  const summarizedThrough = new Map<AgentTeamThreadRef, number>()
  const threads: InboxThreadPlan[] = []
  let thresholdReached = false
  for (const { item, facts, reminders = [] } of input.threads) {
    const threadRef = item.thread.threadRef
    if (reminders.length > 0) immediate.push([threadRef, 'reminder', ...reminders.map(reminder => `${reminder.kind}:${reminder.baselineSequence}`)])
    const owner = input.owns(item.projectRef)
    const waiting = facts.filter(entry => isThresholdFact(entry, owner))
    const now = facts.filter(entry => !isThresholdFact(entry, owner)).map(entry => entry.fact.sequence)
    if (now.length > 0) immediate.push([threadRef, ...now])
    const through = input.summarizedThrough.get(threadRef) ?? 0
    if (waiting.filter(entry => entry.fact.sequence > through).length >= INBOX_THRESHOLD_UPDATES) thresholdReached = true
    if (waiting.length > 0) summarizedThrough.set(threadRef, waiting.at(-1)!.fact.sequence)
    threads.push(Object.freeze({ threadRef, role: owner ? 'owner' : item.attention === undefined ? 'member' : 'follower',
      delivery: now.length > 0 || reminders.length > 0 ? 'immediate' : 'threshold', thresholdCount: waiting.length }))
  }
  for (const { projectRef, entries } of input.main) {
    if (entries.length > 0) immediate.push([projectRef, ...entries.map(entry => entry.sequence)])
  }
  const signature = immediate.length === 0 ? '' : JSON.stringify(immediate)
  const trigger = signature !== '' && signature !== input.covered ? 'immediate' : thresholdReached ? 'threshold' : undefined
  return Object.freeze({ trigger, signature, summarizedThrough, threads: Object.freeze(threads) })
}

