/** Identity of one Member × Thread attention period. */
export interface AgentTeamThreadAttentionKey {
  readonly memberId: AgentTeamMemberId
  readonly threadRef: AgentTeamThreadRef
}

/** Sparse direct-priority marker for one structured Message mention. */
export interface AgentTeamDirectMarker {
  readonly memberId: AgentTeamMemberId
  readonly threadRef: AgentTeamThreadRef
  readonly messageRef: AgentTeamMessageRef
  readonly sequence: number
}

/** Sparse marker retaining a relevant Task or Claim Activity after Attention ends. */
export interface AgentTeamActivityMarker {
  readonly memberId: AgentTeamMemberId
  readonly threadRef: AgentTeamThreadRef
  readonly activityRef: AgentTeamActivityRef
  readonly sequence: number
}

/** One immutable Main stream Message: a Project-level conversation entry that belongs to no Thread. Rules version 2 and later only. */
export interface AgentTeamMainMessage {
  readonly messageRef: AgentTeamMessageRef
  readonly projectRef: AgentTeamProjectRef
  readonly scope: 'main'
  readonly sender: AgentTeamMemberId
  readonly body: string
  readonly attachments?: readonly AgentTeamMessageAttachment[] | undefined
  /** The Main stream Message this one answers; a Thread Message is never a valid target. */
  readonly replyToMessageRef?: AgentTeamMessageRef
  readonly sequence: number
  readonly occurredAt: string
}

/** Project-level change shown in the Main stream: a Human grant or withdrawal of Project ownership. Rules version 2 and later only. */
export interface AgentTeamMainActivity {
  readonly activityRef: AgentTeamActivityRef
  readonly projectRef: AgentTeamProjectRef
  readonly kind: 'owner-added' | 'owner-removed'
  /** The Agent Member whose ownership changed. */
  readonly memberId: AgentTeamMemberId
  readonly actor: AgentTeamMemberId
  readonly sequence: number
  readonly occurredAt: string
}

/** Sparse direct marker for one Main stream Message that mentions or answers a Member. Its own shape: the Thread marker requires a `threadRef`. */
export interface AgentTeamMainMessageMarker {
  readonly memberId: AgentTeamMemberId
  readonly projectRef: AgentTeamProjectRef
  readonly messageRef: AgentTeamMessageRef
  readonly sequence: number
}

/** Sparse marker for one Main stream Activity that concerns a Member. */
export interface AgentTeamMainActivityMarker {
  readonly memberId: AgentTeamMemberId
  readonly projectRef: AgentTeamProjectRef
  readonly activityRef: AgentTeamActivityRef
  readonly sequence: number
}

/** Main stream marker: what a non-owner's Main stream unread consists of, and what an owner keeps on top of the ordinary unread. */
export type AgentTeamMainMarker = AgentTeamMainMessageMarker | AgentTeamMainActivityMarker

/** A Host reminder aimed at one Member. It is not a public Thread fact: reading its Task consumes only the recipient's marker. */
export interface AgentTeamReminderMarker {
  readonly memberId: AgentTeamMemberId
  readonly threadRef: AgentTeamThreadRef
  readonly taskRef: AgentTeamTaskRef
  readonly kind: 'review-backlog' | 'stalled'
  readonly baselineSequence: number
  readonly sequence: number
}

/** Durable changes to private Member inbox state carried by one operation. */
export interface AgentTeamInboxDelta {
  readonly attention: {
    /** New or replacement current Attention records. */
    readonly set: readonly AgentTeamThreadAttention[]
    /** Attention periods ended by this operation. */
    readonly removed: readonly AgentTeamThreadAttentionKey[]
  }
  readonly directMarkers: {
    readonly added: readonly AgentTeamDirectMarker[]
    readonly removed: readonly AgentTeamDirectMarker[]
  }
  readonly activityMarkers: {
    readonly added: readonly AgentTeamActivityMarker[]
    readonly removed: readonly AgentTeamActivityMarker[]
  }
  /** Present only when it changes something, so existing deltas keep their stored shape. */
  readonly reminderMarkers?: {
    readonly added: readonly AgentTeamReminderMarker[]
    readonly removed: readonly AgentTeamReminderMarker[]
  }
  /** Present only when it changes something, so every rules-version-1 delta keeps its stored bytes. */
  readonly mainMarkers?: {
    readonly added: readonly AgentTeamMainMarker[]
    readonly removed: readonly AgentTeamMainMarker[]
  }
}

/** One Direction Claim retained as Task progress history. */
export interface AgentTeamClaim {
  readonly claimRef: AgentTeamClaimRef
  readonly taskRef: AgentTeamTaskRef
  readonly threadRef: AgentTeamThreadRef
  readonly owner: AgentTeamMemberId
  readonly direction: string
  readonly normalizedDirection: string
  readonly state: 'active' | 'done' | 'released'
}

interface AgentTeamActivityBase {
  readonly activityRef: AgentTeamActivityRef
  readonly taskRef: AgentTeamTaskRef
  readonly threadRef: AgentTeamThreadRef
  readonly actor: AgentTeamMemberId
  readonly sequence: number
}

export interface AgentTeamClaimActivity extends AgentTeamActivityBase {
  readonly kind: 'claim' | 'done' | 'release'
  readonly claimRef: AgentTeamClaimRef
}

export interface AgentTeamTaskActivity extends AgentTeamActivityBase {
  readonly kind: 'promote' | 'accept' | 'close' | 'reopen' | 'transfer'
  readonly from?: AgentTeamMemberId
  readonly to?: AgentTeamMemberId
  /** Claims atomically released by close; absent for other Task transitions. */
  readonly releasedClaimRefs?: readonly AgentTeamClaimRef[] | undefined

}).strict()

const activityBase = {
  activityRef: activityRefSchema,
  taskRef: taskRefSchema,
  threadRef: threadRefSchema,
  actor: memberIdSchema,
  sequence: z.number().int().positive(),
}

const claimActivitySchema = z.object({
  ...activityBase,
  kind: z.union([z.literal('claim'), z.literal('done'), z.literal('release')]),
  claimRef: claimRefSchema,
}).strict()

const taskActivitySchema = z.object({
  ...activityBase,
  kind: z.union([z.literal('promote'), z.literal('accept'), z.literal('close'), z.literal('reopen'), z.literal('transfer')]),
  from: memberIdSchema.optional(),
  to: memberIdSchema.optional(),
  releasedClaimRefs: z.array(claimRefSchema).min(1).optional(),
  completedClaimRefs: z.array(claimRefSchema).min(1).optional(),
  acceptedClaimRefs: z.array(claimRefSchema).optional(),
}).strict()

const claimsReleasedActivitySchema = z.object({
  ...activityBase,
  kind: z.literal('claims_released'),
  claimRefs: z.array(claimRefSchema).min(1),
}).strict()

const activitySchema = z.discriminatedUnion('kind', [claimActivitySchema, taskActivitySchema, claimsReleasedActivitySchema])

const threadFactSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('message'), sequence: z.number().int().positive(), message: messageSchema,
    mentions: z.array(memberIdSchema), occurredAt: z.string().datetime().optional() }).strict(),
  z.object({ kind: z.literal('activity'), sequence: z.number().int().positive(), activity: activitySchema,
    occurredAt: z.string().datetime().optional() }).strict(),
])

const readFactSchema = z.object({
  fact: threadFactSchema,
  unread: z.boolean(),
  direct: z.boolean(),
}).strict()

const claimOperation = (kind: 'team/claim-created' | 'team/claim-done' | 'team/claim-released') => z.object({
  ...operationBase,
  previousOperationId: operationIdSchema.nullable(),
  kind: z.literal(kind),
  data: z.object({
    workspaceId: workspaceIdSchema,
    baseRevision: z.number().int().positive(),
    activity: claimActivitySchema,

    })),
  })
}

/** Live participation addresses; paths remain owned by the Harness registry. */
/** Active Projects the Agent's Member owns, for the per-step Member context; undefined while the ledger predates Project owners. */
ownedProjectsForAgent(agent: Agent): readonly AgentTeamProject[] | undefined {
  const member = this.memberForAgent(agent)
  const ledger = this.requireLedger()
  if (member === undefined || ledger.status().rulesVersion < 2) return undefined
  return ledger.ownedProjects(member.memberId)
}

workspacesForAgent(agent: Agent): readonly { readonly workspaceId: WorkspaceId; readonly path: string | undefined; readonly default: boolean }[] {
  const actor = this.memberActor(agent)
  const member = this.requireLedger().getMember(actor.memberId)!
  return Object.freeze(this.requireLedger().workspacesOf(actor.memberId).map(workspaceId => Object.freeze({
    workspaceId, path: this.ctx.workspaceRegistry.get(workspaceId)?.path, default: workspaceId === member.workspaceId,
  })))
}

/** Agent-only bounded discovery projection; participation list carries registry titles when known. */
viewForAgent(agent: Agent, request: AgentTeamViewRequest): AgentTeamView {
  const member = this.memberForAgent(agent)
  if (member === undefined) throw new Error('Agent is not an active Team Member')
  if (!this.requireLedger().participatesIn(member.memberId, request.workspaceId)) throw new Error('Member cannot view another Workspace')
  const view = this.requireLedger().view(request, member.memberId)
  return Object.freeze({ ...view, workspaces: Object.freeze(view.workspaces.map(participation => {
    const title = this.ctx.workspaceRegistry.get(participation.workspaceId)?.title
    return title === undefined ? participation : Object.freeze({ ...participation, title })
  })) })
}

validateLedger(): void {
  this.requireLedger().validate()
}

/**
 * Validate the durable ledger for the invariant's mount check. The
 * constructor already re-derived every durable record against its own
 * scratch projection, so this adopts that conclusion once while nothing has
 * committed since; every other call, and every commit-driven validation,
 * replays the whole table again.
 */
validateLedgerAtMount(): void {
  this.requireLedger().validateAtMount()
}

/**
 * Why a carried-input replay did not run. Each reason is a state the Host
 * accepts and continues from, never an error: a blocked replay would turn a
 * problem in a Session the Member no longer runs in into permanent
 * unavailability.
 */
private skipCarriedInput(memberId: AgentTeamMemberId, previousSessionId: SessionId, reason: 'started-generation' | 'corrupt' | 'refused', detail?: string): 0 {
  const member = this.memberLabel(memberId)
  if (reason === 'started-generation') {
    // Nothing is lost: the carried input was delivered after activation (or
    // superseded) before the generation's first own turn could run.
    this.ctx.logger.info(`agent-team: skipping carried-input replay for member '${member}': the current Session '${previousSessionId}' already started a generation`)
    return 0
  }
  const fault = reason === 'corrupt'
    ? 'is corrupt'
    : 'is refused by the session-format migration'
  this.ctx.logger.warn(`agent-team: previous Session '${previousSessionId}' holding carried input for member '${member}' ${fault}: ${detail}; skipping the replay`)
  return 0
}

private async replayCarriedInput(member: AgentTeamAgentMember, agent: Agent, generationStarted: boolean): Promise<number> {
  const transition = this.requireLedger().lastTransitionForMember(member.memberId)
  if (transition === undefined || transition.targetSessionId !== agent.session.id) return 0
  if (generationStarted && transition.inputFromSeq === undefined) return this.skipCarriedInput(member.memberId, agent.session.id, 'started-generation')
  let inspectionEvents: readonly SessionEvent[]
  let inspectionInherited: SessionLogOffset
  const previousRead = await this.sessionReader.read(transition.previousSessionId)
  if (!previousRead.ok) {
    const failure = previousRead.failure
    if (failure.kind === 'corrupt') return this.skipCarriedInput(member.memberId, transition.previousSessionId, 'corrupt', failure.detail)
    if (failure.kind === 'refused') return this.skipCarriedInput(member.memberId, transition.previousSessionId, 'refused', failure.detail)
    throw new StoredSessionReadError(`the previous Session '${transition.previousSessionId}' holding the Member's carried input is unreadable (${failure.kind}): ${failure.detail}`, failure)
  }
  inspectionEvents = previousRead.inspection.events
  inspectionInherited = previousRead.inspection.inheritedEventCount
  const state = foldTeamContextProjection(
    inspectionEvents,
    { sessionId: transition.previousSessionId, inheritedEventCount: inspectionInherited,
      ...(transition.inputFromSeq === undefined ? {} : { inputFromSeq: transition.inputFromSeq }) },
  )
  const carried = carriedInputOf(state, inspectionEvents)
  if (carried.length === 0) return 0
  const known = new Set<string>()
  for (const event of agent.session.ownEvents()) {
    if (event.type !== 'user/message') continue
    const id = (event.data as { id?: string }).id
    if (id !== undefined) known.add(id)
  }
  for (const pending of [...agent.inbox.nextStep, ...agent.inbox.nextTurn]) {
    known.add(pending.id)
  }
  let redelivered = 0
  for (const message of carried) {
    if (known.has(message.id)) continue
    agent.followup(message)
    redelivered += 1
  }
  if (redelivered > 0) this.ctx.logger.info(`agent-team: redelivered ${redelivered} carried input message(s) for member '${this.memberLabel(member.memberId)}' after the generation crash recovery`)
  return redelivered
}

/**
 * Jobs this Agent owns that cannot survive a generation swap: any
 * running/stopping job, and any settled job whose terminal output was
 * never reported (disposal would silently discard it). In-place hard
 * compaction is exempt — it never cancels the owner.
 */
private ownedJobsBlockingRecycle(agent: Agent): readonly string[] {
  const jobs = agent.ctx.get('jobs')
  if (jobs === undefined) return []
  return jobs.list(agent)
    .filter((job: { status: string; reported: boolean }) => job.status === 'running' || job.status === 'stopping' || ((job.status === 'completed' || job.status === 'killed' || job.status === 'failed') && !job.reported))
    .map((job: { id: string; label: string }) => `${job.label} (${job.id})`)
}

private emitCommittedOutcome<T extends { readonly kind: string; readonly receipt?: AgentTeamOperationReceipt }>(
  result: { readonly committed: boolean; readonly value: T },
): void {
  if (result.committed && result.value.kind === 'committed' && result.value.receipt !== undefined) this.emitCommitted(result.value.receipt)
}

private assertProjectMembersAvailable(memberIds: readonly AgentTeamMemberId[] | undefined): void {
  for (const memberId of memberIds ?? []) {
    const member = this.requireLedger().getMember(memberId)
    if (member === undefined) throw new Error(`unknown Agent Member '${memberId}'`)
    if (this.memberStatus(member).availability !== 'active') throw new Error(`Agent Member '${memberId}' is not available for Project membership`)

attentionStatus(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: {
  workspaceId: WorkspaceId
  threadRef?: AgentTeamThreadRef | undefined
  taskRef?: AgentTeamTaskRef | undefined
}): AgentTeamThreadAttentionStatus {
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  const { task, thread } = this.threadContextForActor(authorized, request.workspaceId, request)
  const attention = this.attentionFor(authorized.memberId, thread.threadRef)
  return Object.freeze({ ...(task === undefined ? {} : { task }), thread, ...(attention === undefined ? {} : { attention }) })
}

inbox(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: AgentTeamInboxRequest): AgentTeamInbox {
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  return this.inboxForWorkspaces(authorized, [request.workspaceId], request.limit)
}

memberInbox(actor: AgentTeamMemberActor, request: { readonly limit?: number }): AgentTeamInbox {
  const workspaces = this.workspacesOf(actor.memberId)
  for (const workspaceId of workspaces) this.assertActorForWorkspace(actor, workspaceId)
  return this.inboxForWorkspaces(actor, workspaces, request.limit)
}

private inboxForWorkspaces(authorized: AgentTeamHumanActor | AgentTeamMemberActor, workspaceIds: readonly WorkspaceId[], requestedLimit?: number): AgentTeamInbox {
  const limit = requestedLimit ?? 50
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('inbox limit must be an integer between 1 and 100')
  const taskNumbers = new Map(workspaceIds.flatMap(workspaceId => [...this.taskNumbers(workspaceId)]))
  const unreadThreads = new Set<AgentTeamThreadRef>()
  // Candidates carry only what ranking and the totals need; a row's preview
  // text, actor and live Claim owners are materialized only for the rows
  // this response returns.
  type Candidate = { readonly workspaceId: WorkspaceId; readonly projectRef: AgentTeamProjectRef; readonly projectName: string
    readonly task?: AgentTeamTask; readonly taskNumber?: number; readonly thread: AgentTeamThread
    readonly unreadCount: number; readonly directCount: number
    readonly newestSequence: number; readonly newestOccurredAt: string; readonly newestActor: AgentTeamInboxActor
    readonly reminders: readonly import('./types/requests-results.ts').AgentTeamInboxReminder[]
    readonly attention?: AgentTeamThreadAttention }
  const candidates: Candidate[] = []
  for (const threadRef of this.inboxCandidateThreads(authorized.memberId)) {
    const thread = this.state.threads.get(threadRef)
    if (thread === undefined) continue
    const projectRef = this.projectRefForThread(thread.threadRef)
    if (projectRef === undefined) continue
    const project = this.state.projects.get(projectRef)
    if (project === undefined || !workspaceIds.includes(project.workspaceId)) continue
    if (this.visibleProject(project) === undefined) continue
    const workspaceId = project.workspaceId
    if (authorized.kind === 'member' && !this.isProjectMember(projectRef, authorized.memberId)) continue
    const unread = this.unreadFor(authorized.memberId, thread.threadRef)
    const reminders = this.remindersFor(authorized.memberId, thread.threadRef)
    if (unread.length === 0 && reminders.length === 0) continue
    unreadThreads.add(thread.threadRef)
    const task = thread.taskRef === undefined ? undefined : this.state.tasks.get(thread.taskRef)
    const directCount = unread.filter(item => item.direct).length + reminders.length
    const attention = this.attentionFor(authorized.memberId, thread.threadRef)
    const newest = unread.at(-1)?.fact
    const latestReminder = reminders.at(-1)
    const reminderIsNewest = latestReminder !== undefined && latestReminder.sequence > (newest?.sequence ?? 0)
    const newestSequence = reminderIsNewest ? latestReminder.sequence : newest?.sequence ?? latestReminder?.sequence ?? 0
    const newestOccurredAt = reminderIsNewest ? latestReminder.occurredAt : newest?.occurredAt ?? latestReminder?.occurredAt ?? ''
    const newestActor = reminderIsNewest || newest === undefined
      ? Object.freeze({ memberId: AGENT_TEAM_HUMAN_MEMBER_ID, name: 'Agent Team' }) : this.inboxActorFor(newest)
    const taskNumber = task === undefined ? undefined : taskNumbers.get(task.taskRef)
    candidates.push({ workspaceId, projectRef, projectName: project.name,
      ...(task === undefined ? {} : { task }), ...(taskNumber === undefined ? {} : { taskNumber }), thread,
      unreadCount: unread.length + reminders.length, directCount, newestSequence, newestOccurredAt, newestActor, reminders,
      ...(attention === undefined ? {} : { attention }) })
  }
  candidates.sort((left, right) => right.directCount - left.directCount || right.newestSequence - left.newestSequence || left.thread.threadRef.localeCompare(right.thread.threadRef))
  const selected = candidates.slice(0, limit).map(candidate => Object.freeze({ workspaceId: candidate.workspaceId, projectRef: candidate.projectRef,
    projectName: candidate.projectName, ...(candidate.task === undefined ? {} : { task: candidate.task }),
    ...(candidate.taskNumber === undefined ? {} : { taskNumber: candidate.taskNumber }), thread: candidate.thread,
    unreadCount: candidate.unreadCount, directCount: candidate.directCount, reminders: candidate.reminders,
    previewText: boundedOpeningLine(this.threadAnchor(candidate.thread.threadRef).body, ONE_LINE_GIST_MAX_CHARACTERS),
    newestSequence: candidate.newestSequence, newestOccurredAt: candidate.newestOccurredAt,
    newestActor: candidate.newestActor, liveClaimOwners: this.liveClaimOwners(candidate.task),
    ...(candidate.attention === undefined ? {} : { attention: candidate.attention }) }))
  const recent = authorized.kind === 'human'
    ? this.recentInboxItems(authorized.memberId, workspaceIds[0]!, unreadThreads, taskNumbers)
    : Object.freeze([] as AgentTeamInboxItem[])
  const main = this.mainInboxItems(authorized.memberId, workspaceIds)
  return Object.freeze({ humanMemberId: this.initialization().data.humanMemberId,
    items: Object.freeze(selected), hasMore: candidates.length > selected.length, main, recent,
    totalUnreadCount: [...candidates, ...main].reduce((sum, item) => sum + item.unreadCount, 0),
    totalDirectCount: [...candidates, ...main].reduce((sum, item) => sum + item.directCount, 0) })
}

taskBoard(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: AgentTeamTaskBoardRequest): AgentTeamTaskBoard {
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  return this.taskBoardFor(authorized, [request.workspaceId], request)
}

