const keyOf = marker => [marker.memberId, marker.taskRef, marker.kind, marker.baselineSequence].join('|')
const percent = (part, total) => total === 0 ? null : Math.round(part / total * 1000) / 10
const increment = (map, key, amount = 1) => map.set(key, (map.get(key) ?? 0) + amount)

function readOperations(path) {
  const database = new DatabaseSync(path, { readOnly: true })
  try {
    return database.prepare('SELECT key, value FROM u_agent_team_operations').all()
      .map(row => [row.key, agentTeamOperationSchema.parse(JSON.parse(row.value))])
      .sort((left, right) => left[1].sequence - right[1].sequence)
  } finally { database.close() }
}

function newState() {
  return { projects: new Map(), members: new Map(), owners: new Map(), tasks: new Map(), claims: new Map(),
    follows: new Map(), statusBaselines: new Map(), latestFacts: new Map(), reminders: new Map(), reminderEpisodes: new Map() }
}

function apply(state, operation) {
  const data = operation.data
  if (operation.kind === 'team/project-created') {
    state.projects.set(data.project.projectRef, data.project)
    state.owners.set(data.project.projectRef, new Set())
  }
  if (operation.kind === 'team/project-archived') state.projects.set(data.project.projectRef, data.project)
  if (data.member !== undefined) state.members.set(data.member.memberId, data.member)
  if (operation.kind === 'team/project-owner-added') state.owners.get(data.projectRef)?.add(data.memberId)
  if (operation.kind === 'team/project-owner-removed') state.owners.get(data.projectRef)?.delete(data.memberId)
  if (releaseKinds.has(operation.kind) && data.member !== undefined) {
    for (const [projectRef, owners] of state.owners) {
      if (state.projects.get(projectRef)?.workspaceId === data.member.workspaceId) owners.delete(data.member.memberId)
    }
  }
  if (operation.kind === 'team/project-archived') state.owners.set(data.project.projectRef, new Set())
  if (operation.kind === 'team/thread-started') state.latestFacts.set(data.thread.threadRef, operation.sequence)
  if (operation.kind === 'team/thread-replied') state.latestFacts.set(data.thread.threadRef, operation.sequence)
  if (operation.kind === 'team/claim-created') state.claims.set(data.claim.claimRef, { ...data.claim, createdSequence: operation.sequence })
  if (operation.kind === 'team/claim-done' || operation.kind === 'team/claim-released') state.claims.set(data.claim.claimRef, { ...state.claims.get(data.claim.claimRef), ...data.claim })
  if (data.task !== undefined) {
    const previous = state.tasks.get(data.task.taskRef)
    state.tasks.set(data.task.taskRef, data.task)
    if (data.task.status === 'in_review' && previous?.status !== 'in_review') state.statusBaselines.set(data.task.taskRef, operation.sequence)
  }
  if (data.transfers !== undefined) for (const transfer of data.transfers) {
    const task = state.tasks.get(transfer.taskRef)
    if (task !== undefined) state.tasks.set(task.taskRef, { ...task, accountable: transfer.to })
  }
  if (data.inbox !== undefined) {
    for (const attention of data.inbox.attention.set) state.follows.set(`${attention.memberId}|${attention.threadRef}`, attention)
    for (const attention of data.inbox.attention.removed) state.follows.delete(`${attention.memberId}|${attention.threadRef}`)
  }
  if (operation.kind === 'team/reminder-raised') {
    const marker = data.inbox.reminderMarkers.added[0]
    state.reminders.set(keyOf(marker), { marker, operation, invalid: undefined })
    state.reminderEpisodes.set(`${data.taskRef}|${data.kind}|${data.recipient}|${data.baselineSequence}`, operation.sequence)
  }
}

function liveReminder(state, marker) {
  const task = state.tasks.get(marker.taskRef)
  if (task === undefined || task.resolution !== 'open' || state.projects.get(task.projectRef)?.state !== 'active') return false
  if (marker.kind === 'review-backlog') {
    const recipient = reviewReminderRecipient(task,
      (projectRef, memberId) => memberId === HUMAN || state.owners.get(projectRef)?.has(memberId) === true,
      (taskRef, memberId) => [...state.claims.values()].some(claim => claim.taskRef === taskRef && claim.owner === memberId))
    return task.status === 'in_review' && state.statusBaselines.get(task.taskRef) === marker.baselineSequence && recipient === marker.memberId
  }
  return task.status === 'in_progress' && task.accountable === marker.memberId
    && (state.latestFacts.get(task.threadRef) ?? 0) <= marker.baselineSequence
    && (state.reminderEpisodes.get(`${marker.taskRef}|${marker.kind}|${marker.memberId}|${marker.baselineSequence}`) ?? marker.sequence) === marker.sequence
}

function agentReplyMetric(state, operation, scope, message) {
  const parent = message.replyToMessageRef
  const recipients = new Set(operation.data.mentions ?? [])
  if (parent !== undefined) {
    const sender = parent === undefined ? undefined : state.messageSenders.get(parent)
    if (sender !== undefined && sender !== message.sender) recipients.add(sender)
  }
  return { scope, sequence: operation.sequence, occurredAt: operation.occurredAt,
    agentToAgent: message.sender !== HUMAN && [...recipients].some(memberId => memberId !== HUMAN) }
}

export function calculateTrialMetrics(records) {
  const operations = [...records].sort((left, right) => left[1].sequence - right[1].sequence).map(([, operation]) => operation)
  const adoption = operations.find(operation => operation.kind === 'team/rules-version-adopted' && operation.data.version >= 2)
  const baselineSequence = adoption?.sequence ?? (operations.length > 0 ? operations[0].sequence : 0)
  const baselineMs = Date.parse(adoption?.occurredAt ?? operations[0]?.occurredAt ?? new Date(0).toISOString())
  const trialOperations = operations.filter(operation => operation.sequence >= baselineSequence)
  const state = newState()
  state.messageSenders = new Map()
  const replies = []
  const mainPostsByNonOwner = []
  const resolutions = []
  const immediate = new Map()
  const threshold = new Map()
  const days = new Map()
  const dayFor = operation => Math.floor((Date.parse(operation.occurredAt) - baselineMs) / DAY_MS) + 1
  const notify = (memberId, operation, amount = 1) => {
    if (memberId === HUMAN || !state.members.has(memberId)) return
    increment(immediate, memberId, amount)
    increment(days, `${dayFor(operation)}|${memberId}`, amount)
  }
  for (const operation of trialOperations) {
    const data = operation.data
    const projectRef = data.projectRef ?? data.project?.projectRef ?? data.task?.projectRef ?? data.anchor?.projectRef ?? data.message?.projectRef
    const actor = operation.actor.kind === 'host' ? undefined : operation.actor.memberId
    const owners = projectRef === undefined ? new Set() : state.owners.get(projectRef) ?? new Set()
    if (operation.kind === 'team/reminder-raised') {
      const marker = data.inbox.reminderMarkers.added[0]
      notify(marker.memberId, operation)
    } else if (data.inbox !== undefined) {
      for (const marker of data.inbox.directMarkers.added) notify(marker.memberId, operation)
      for (const marker of data.inbox.activityMarkers.added) notify(marker.memberId, operation)
      for (const marker of data.inbox.mainMarkers?.added ?? []) notify(marker.memberId, operation)
      if (operation.kind === 'team/main-message-posted') {
        for (const memberId of owners) if (memberId !== actor) notify(memberId, operation)
      }
      if (operation.kind === 'team/thread-started' && data.kind === 'discussion') {
        for (const memberId of owners) if (memberId !== actor) notify(memberId, operation)
      }
      if (operation.kind === 'team/thread-replied') {
        for (const [key, attention] of state.follows) {
          const [memberId, threadRef] = key.split('|')
          if (threadRef !== data.thread.threadRef || memberId === actor) continue
          if (owners.has(memberId)) increment(threshold, memberId)
          else notify(memberId, operation)
        }
      }
    }
    if (operation.kind === 'team/thread-replied') replies.push(agentReplyMetric(state, operation, 'thread', data.message))
    if (operation.kind === 'team/main-message-posted') {
      replies.push(agentReplyMetric(state, operation, 'main', data.message))
      if (actor !== undefined && actor !== HUMAN && !owners.has(actor)) mainPostsByNonOwner.push(operation.sequence)
    }
    if (operation.kind === 'team/task-changed' && (data.activity.kind === 'accept' || data.activity.kind === 'close')) {
      resolutions.push({ sequence: operation.sequence, occurredAt: operation.occurredAt, kind: data.activity.kind,
        byHuman: operation.actor.kind === 'human', taskRef: data.task.taskRef })
    }
    if (operation.kind === 'team/message-sent' || operation.kind === 'team/thread-replied' || operation.kind === 'team/thread-started') {
      const message = data.message ?? data.anchor
      state.messageSenders.set(message.messageRef, message.sender)
    }
    if (operation.kind === 'team/main-message-posted') state.messageSenders.set(data.message.messageRef, data.message.sender)
    for (const pending of state.reminders.values()) {
      if (pending.invalid === undefined && !liveReminder(state, pending.marker)) pending.invalid = { sequence: operation.sequence, occurredAt: operation.occurredAt }
    }
    for (const marker of data.inbox?.reminderMarkers?.removed ?? []) {
      const pending = state.reminders.get(keyOf(marker))
      if (pending !== undefined) pending.consumed = { sequence: operation.sequence, kind: operation.kind }
      state.reminders.delete(keyOf(marker))
    }
    apply(state, operation)
  }
  const reminderOperations = trialOperations.filter(operation => operation.kind === 'team/reminder-raised')
  const historicalReminders = [...state.reminders.values()]
  const invalidBeforeRead = historicalReminders.filter(entry => entry.invalid !== undefined)
  const currentUnread = historicalReminders.filter(entry => entry.consumed === undefined)
  const lastSequence = trialOperations.at(-1)?.sequence ?? 0
  const lastMs = Date.parse(trialOperations.at(-1)?.occurredAt ?? new Date(baselineMs).toISOString())
  const elapsedDays = trialOperations.length === 0 ? 0 : Math.max(1, Math.floor((lastMs - baselineMs) / DAY_MS) + 1)
  const immediateFacts = Object.fromEntries([...immediate].sort())
  const ownerDaily = [...days].map(([key, count]) => {
    const [day, memberId] = key.split('|')
    return { day: Number(day), memberId, immediateNotificationFacts: count }
  })
  const thresholdGroups = [...threshold].reduce((count, [, facts]) => count + Math.floor(facts / 5), 0)
  return {
    range: { baselineSequence, lastSequence, baselineOccurredAt: new Date(baselineMs).toISOString(),
      lastOccurredAt: new Date(lastMs).toISOString(), elapsedDays, completeDays: Math.max(0, Math.floor((lastMs - baselineMs) / DAY_MS)) },
    agentReplies: { total: replies.length, agentToAgent: replies.filter(reply => reply.agentToAgent).length,
      agentToAgentPercent: percent(replies.filter(reply => reply.agentToAgent).length, replies.length),
      byScope: Object.fromEntries(['thread', 'main'].map(scope => [scope, {
        total: replies.filter(reply => reply.scope === scope).length,
        agentToAgent: replies.filter(reply => reply.scope === scope && reply.agentToAgent).length }])) },
    resolutions: { total: resolutions.length, byHuman: resolutions.filter(entry => entry.byHuman).length,
      byHumanPercent: percent(resolutions.filter(entry => entry.byHuman).length, resolutions.length),
      acceptsByHuman: resolutions.filter(entry => entry.byHuman && entry.kind === 'accept').length,
      closesByHuman: resolutions.filter(entry => entry.byHuman && entry.kind === 'close').length },
    ownerDelivery: { immediateNotificationFactsByMember: immediateFacts,
      immediateNotificationFactsPerElapsedDayByMember: Object.fromEntries([...immediate].map(([memberId, count]) => [memberId, elapsedDays === 0 ? 0 : Math.round(count / elapsedDays * 100) / 100])),
      byDay: ownerDaily, ownerOrdinaryThreadFacts: Object.fromEntries([...threshold].sort()), thresholdGroupsOfFive: thresholdGroups },
    mainStream: { nonOwnerPosts: mainPostsByNonOwner.length },
    reminders: { raised: reminderOperations.length,
      byKind: Object.fromEntries(['review-backlog', 'stalled'].map(kind => [kind, reminderOperations.filter(operation => operation.data.kind === kind).length])),
      byRecipient: Object.fromEntries(reminderOperations.reduce((map, operation) => increment(map, operation.data.recipient), new Map())),
      unread: currentUnread.length, staleUnread: currentUnread.filter(entry => entry.invalid !== undefined).length,
      invalidatedBeforeConsumption: invalidBeforeRead.length,
      staleUnreadSamples: currentUnread.filter(entry => entry.invalid !== undefined).slice(0, 20).map(entry => ({
        ...entry.marker, reminderSequence: entry.operation.sequence, invalidAtSequence: entry.invalid.sequence })) },
    limitations: [
      'The ledger has no delivery-attempt or wake receipt. Immediate notification facts and threshold groups are not measured Agent interruptions.',
      'Thread ordinary delivery counts owners only; accountable non-owners and historical Attention changes need separate instrumentation for exact delivery totals.',
      'A reminder superseded before its marker was consumed is a review lead, not a confirmed false positive. Confirm false positives manually.',
    ],
  }
}

function run(path) {
  const records = readOperations(path)
  const started = performance.now()
  const ledger = new AgentTeamLedger({ entries: () => records.entries() })
  ledger.validate()
  const result = calculateTrialMetrics(records)
  result.validation = { records: records.length, replayValidationMs: Math.round(performance.now() - started), result: 'passed' }
  if (process.argv.includes('--json')) console.log(JSON.stringify(result, null, 2))
  else {
    console.log(`账本副本 ${path}`)
    console.log(`重放校验：${result.validation.records} 条通过；统计范围 ${result.range.baselineSequence}–${result.range.lastSequence}；经过 ${result.range.elapsedDays} 个 UTC 自然日`)
    console.log(`Agent 回复：${result.agentReplies.total} 条，Agent 之间 ${result.agentReplies.agentToAgent} 条（${result.agentReplies.agentToAgentPercent ?? 'n/a'}%）`)
    console.log(`accept/close：${result.resolutions.total} 次，Human 执行 ${result.resolutions.byHuman} 次（${result.resolutions.byHumanPercent ?? 'n/a'}%）`)
    console.log(`非 owner 的 Main stream 发言：${result.mainStream.nonOwnerPosts} 条`)
    console.log(`提醒：${result.reminders.raised} 条；未读 ${result.reminders.unread} 条；已失效未读 ${result.reminders.staleUnread} 条；失效后才消费 ${result.reminders.invalidatedBeforeConsumption} 条`)
    console.log('owner 每个 UTC 日的 immediate 候选事实：')
    console.log(JSON.stringify(result.ownerDelivery.byDay, null, 2))
    console.log(`注意：${result.limitations.join('\n')}`)
    console.log('确认误报数：人工复查 staleUnreadSamples 与已消费提醒后另行记录，本脚本不自动判定。')
  }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const path = process.argv.slice(2).find(argument => !argument.startsWith('--')) ?? `${process.env.DSH_HOME ?? `${process.env.HOME}/.dsh`}/storages/agent_team.sqlite`
  if (process.argv.includes('--help')) console.log('usage: node --import tsx scripts/team-trial-metrics.mjs [ledger-copy.sqlite] [--json]')
  else run(path)
}

