13	const percent = (part, total) => total === 0 ? null : Math.round(part / total * 1000) / 10
14	const increment = (map, key, amount = 1) => map.set(key, (map.get(key) ?? 0) + amount)
15	
16	function readOperations(path) {
17	  const database = new DatabaseSync(path, { readOnly: true })
18	  try {
19	    return database.prepare('SELECT key, value FROM u_agent_team_operations').all()
20	      .map(row => [row.key, agentTeamOperationSchema.parse(JSON.parse(row.value))])
21	      .sort((left, right) => left[1].sequence - right[1].sequence)
22	  } finally { database.close() }
23	}
24	
