39	  if (operation.kind === 'team/project-owner-removed') state.owners.get(data.projectRef)?.delete(data.memberId)
40	  if (releaseKinds.has(operation.kind) && data.member !== undefined) {
41	    for (const [projectRef, owners] of state.owners) {
42	      if (state.projects.get(projectRef)?.workspaceId === data.member.workspaceId) owners.delete(data.member.memberId)
43	    }
44	  }
45	  if (operation.kind === 'team/project-archived') state.owners.set(data.project.projectRef, new Set())
46	  if (operation.kind === 'team/thread-started') state.latestFacts.set(data.thread.threadRef, operation.sequence)
47	  if (operation.kind === 'team/thread-replied') state.latestFacts.set(data.thread.threadRef, operation.sequence)
48	  if (operation.kind === 'team/claim-created') state.claims.set(data.claim.claimRef, { ...data.claim, createdSequence: operation.sequence })
49	  if (operation.kind === 'team/claim-done' || operation.kind === 'team/claim-released') state.claims.set(data.claim.claimRef, { ...state.claims.get(data.claim.claimRef), ...data.claim })
50	  if (data.task !== undefined) {
51	    const previous = state.tasks.get(data.task.taskRef)
