6039	  private sortedRecords(): Array<[AgentTeamOperationId, AgentTeamOperation]> {
6040	    const records = [...this.table.entries()].sort((left, right) => left[1].sequence - right[1].sequence)
6041	    const occurrences = new Map<AgentTeamMessageRef, string>()
6042	    const instants = new Map<number, string>()
6043	    for (const [, operation] of records) {
6044	      instants.set(operation.sequence, operation.occurredAt)
6045	      if (operation.kind === 'team/message-sent' || operation.kind === 'team/thread-replied') {
6046	        occurrences.set(operation.data.message.messageRef, operation.data.message.occurredAt ?? operation.occurredAt)
6047	      }
6048	    }
6049	    // Replay against a scratch projection while normalizing, so a legacy
6050	    // cleanup repair sees the same state its validator will.
6051	    const projection = emptyProjection()
6052	    return records.map(([id, operation]) => {
6053	      const normalized = this.repairLegacyProjectCleanup(this.normalizeOperation(operation, occurrences, instants), projection)
6054	      this.applyTo(projection, normalized)
6055	      return [id, normalized]
6056	    })
6057	  }
