6059	  /**
6060	   * Records written by releases that scoped Project archival and Project
6061	   * member-removal inbox cleanup to taskful Threads only (the collector read
6062	   * the Task projection) carry an incomplete inbox when the Project holds a
6063	   * taskless Thread with Attention or markers. They are repaired in memory
6064	   * the same way pre-envelope Thread reads are; any other inbox still fails
6065	   * validation, so a forgery is not silently accepted.
6066	   */
6067	  private repairLegacyProjectCleanup(operation: AgentTeamOperation, projection: Projection): AgentTeamOperation {
6068	    if (operation.kind === 'team/project-archived') {
6069	      const projectRef = operation.data.project.projectRef
6070	      const expected = this.projectArchivalInboxFrom(projection, this.projectThreadRefsFrom(projection, projectRef), projectRef)
6071	      if (!isDeepStrictEqual(operation.data.inbox, expected)
6072	        && isDeepStrictEqual(operation.data.inbox, this.projectArchivalInboxFrom(projection, this.legacyProjectThreadRefs(projection, projectRef), projectRef))) {
6073	        return { ...operation, data: { ...operation.data, inbox: expected } }
6074	      }
6075	      return operation
6076	    }
6077	    if (operation.kind === 'team/project-member-removed') {
6078	      const { projectRef, memberId } = operation.data
6079	      const expected = this.removeMemberThreadInboxFrom(projection, memberId, this.projectThreadRefsFrom(projection, projectRef), new Set([projectRef]))
6080	      if (!isDeepStrictEqual(operation.data.inbox, expected)
6081	        && isDeepStrictEqual(operation.data.inbox, this.removeMemberThreadInboxFrom(projection, memberId, this.legacyProjectThreadRefs(projection, projectRef), new Set([projectRef])))) {
6082	        return { ...operation, data: { ...operation.data, inbox: expected } }
6083	      }
6084	      return operation
6085	    }
6086	    return operation
6087	  }
