1	/**
2	 * In-memory {@link StorageBackend} test double implementing the full KvUnit
3	 * primitive set. Shared test infrastructure: the domain suite uses it to
4	 * exercise open/route/write semantics without touching disk, and the
5	 * workspace package's tests import it by relative path (it lives under
6	 * `tests/`, never `src/`, so it stays out of the published surface).
7	 *
8	 * Fidelity to the backend contract (`dsh-storage` `src/backend.ts`): version
9	 * stamping and `version-mismatch` on reopen, `malformed` never (memory cannot
10	 * corrupt), per-call atomicity trivially, `closed` after close, delete
11	 * idempotence. Media survive across backends through the shared `media` map
12	 * passed into the constructor, which simulates process restarts; stamp
13	 * `versions` directly to fabricate an on-medium version and force a
14	 * `version-mismatch` without a prior open.
15	 * @module
16	 */
17	
18	import { StorageError } from '@deepseek-ai/dsh-storage'
19	import type { KvFacet, KvUnit, KvUnitDescriptor, StorageBackend } from '@deepseek-ai/dsh-storage'
20	
21	/** One unit's medium: tables of records plus the global slot (`null` = never written). */
22	export interface MemoryMedium {
23	  tables: Map<string, Map<string, unknown>>
24	  global: unknown
