1	/**
2	 * Vendored fork of `@deepseek-ai/dsh-storage-sqlite` (`unit.ts`).
3	 *
4	 * Source: deepseek-ai/deepseek-harness
5	 * `packages/storage/storage-sqlite/src/unit.ts` at version 0.1.5-rc.2
6	 * (MIT per that version's package metadata and the repo root LICENSE;
7	 * the stale npm `latest` tag 0.0.1-rc.1 carries BSD-3-Clause metadata).
8	 * Kept identical except the `@module` tag below — see `index.ts` for why
9	 * this backend is vendored and how to sync it.
10	 */
11	
12	/**
13	 * One opened SQLite KV unit: prepared per-table statements over the
14	 * `u_<unit>_<table>` record tables plus this unit's row in the shared
15	 * `unit_globals` table. Each primitive is a single statement, so atomicity
16	 * comes from SQLite itself — no explicit transactions, and no write queue
17	 * (write ordering is the caller's responsibility per the KV contract).
18	 * @module @contexera/dsh-agent-team/sqlite-backend/unit
19	 */
20	
21	import type { DatabaseSync, StatementSync } from 'node:sqlite'
22	import { StorageError } from '@deepseek-ai/dsh-storage'
23	import type { KvUnit, KvUnitDescriptor } from '@deepseek-ai/dsh-storage'
24	import { recordTableName } from './schema.ts'
25	
26	/** Prepared statements for one declared table. */
27	interface TableStatements {
28	  upsert: StatementSync
29	  remove: StatementSync
30	  selectAll: StatementSync
31	}
32	
33	/**
34	 * The SQLite {@link KvUnit}. Constructed by the backend AFTER the unit's
35	 * record tables exist; statements are prepared once here and reused for every
36	 * primitive. Values are stored as JSON text in the `value` column.
37	 */
38	export class SqliteKvUnit implements KvUnit {
39	  private readonly tables = new Map<string, TableStatements>()
40	  private readonly globalUpsert: StatementSync | undefined
41	  private readonly globalSelect: StatementSync | undefined
42	  private closed = false
43	
44	  /**
45	   * @param db - Open database handle owned by the backend (never closed here).
46	   * @param descriptor - Validated descriptor whose record tables already exist.
47	   * @param onClose - Backend callback releasing this unit's open-name slot.
48	   */
49	  constructor(
50	    db: DatabaseSync,
51	    private readonly descriptor: KvUnitDescriptor,
52	    private readonly onClose: () => void,
53	  ) {
54	    for (const table of descriptor.tables) {
55	      // Both name segments are validated against UNIT_NAME_RE by the backend,
56	      // so the physical identifier is safe to interpolate into statement text.
57	      const physical = recordTableName(descriptor.name, table)
58	      this.tables.set(table, {
59	        upsert: db.prepare(
60	          `INSERT INTO "${physical}" (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
61	        ),
62	        remove: db.prepare(`DELETE FROM "${physical}" WHERE key = ?`),
63	        selectAll: db.prepare(`SELECT key, value FROM "${physical}"`),
64	      })
65	    }
66	    this.globalUpsert = descriptor.hasGlobal
67	      ? db.prepare(
68	        'INSERT INTO unit_globals (unit, value) VALUES (?, ?) ON CONFLICT(unit) DO UPDATE SET value = excluded.value',
69	      )
70	      : undefined
71	    this.globalSelect = descriptor.hasGlobal
72	      ? db.prepare('SELECT value FROM unit_globals WHERE unit = ?')
73	      : undefined
74	  }
75	
76	  loadAll(): Promise<{ tables: Record<string, Record<string, unknown>>; global: unknown }> {
77	    return this.settle(() => {
78	      const tables: Record<string, Record<string, unknown>> = {}
79	      for (const [name, statements] of this.tables) {
80	        // Null prototype: record keys are arbitrary strings, so '__proto__'
81	        // must land as an own property instead of mutating the prototype.
82	        const records: Record<string, unknown> = Object.create(null) as Record<string, unknown>
83	        for (const row of statements.selectAll.all() as unknown as Array<{ key: string; value: string }>) {
84	          records[row.key] = this.parseValue(row.value, `table '${name}' key '${row.key}'`)
85	        }
86	        tables[name] = records
87	      }
88	      let global: unknown = null
89	      if (this.globalSelect !== undefined) {
90	        const row = this.globalSelect.get(this.descriptor.name) as { value: string } | undefined
91	        if (row !== undefined) global = this.parseValue(row.value, 'global slot')
92	      }
93	      return { tables, global }
94	    })
95	  }
96	
97	  /** Parse one stored value column, mapping bad JSON to `malformed-medium`. */
98	  private parseValue(text: string, slot: string): unknown {
99	    try {
100	      return JSON.parse(text)
101	    } catch (error) {
102	      throw new StorageError(
103	        'malformed-medium',
104	        `kv unit '${this.descriptor.name}' holds unparsable JSON at ${slot}`,
105	        { cause: error },
106	      )
107	    }
108	  }
109	
110	  putRecord(table: string, key: string, value: unknown): Promise<void> {
111	    return this.settle(() => {
112	      this.statementsFor(table).upsert.run(key, JSON.stringify(value))
113	    })
114	  }
115	
116	  deleteRecord(table: string, key: string): Promise<void> {
117	    return this.settle(() => {
118	      this.statementsFor(table).remove.run(key)
119	    })
120	  }
121	
122	  setGlobal(value: unknown): Promise<void> {
123	    return this.settle(() => {
124	      if (this.globalUpsert === undefined) {
125	        throw new Error(`kv unit '${this.descriptor.name}' declared no global slot`)
126	      }
127	      this.globalUpsert.run(this.descriptor.name, JSON.stringify(value))
128	    })
129	  }
130	
131	  close(): Promise<void> {
132	    if (!this.closed) {
133	      this.closed = true
134	      this.onClose()
135	    }
136	    return Promise.resolve()
137	  }
138	
139	  /**
140	   * Run one synchronous primitive behind the closed guard, mapping a throw to
141	   * a rejection so the Promise-returning contract never throws synchronously.
142	   */
143	  private settle<T>(operation: () => T): Promise<T> {
144	    try {
145	      this.ensureOpen()
146	      return Promise.resolve(operation())
147	    } catch (error) {
148	      // Non-Error throws can only enter through JSON.stringify propagating a
149	      // value's own toJSON throw; wrap those, preserve every real Error.
150	      return Promise.reject(error instanceof Error ? error : new Error(String(error)))
151	    }
152	  }
153	
154	  private ensureOpen(): void {
155	    if (this.closed) {
156	      throw new StorageError('closed', `kv unit '${this.descriptor.name}' is closed`)
157	    }
158	  }
159	
160	  private statementsFor(table: string): TableStatements {
161	    const statements = this.tables.get(table)
162	    if (statements === undefined) {
163	      throw new Error(`kv unit '${this.descriptor.name}' declared no table '${table}'`)
164	    }
165	    return statements
166	  }
167	}
