1	// Usage: node --import tsx scripts/team-trial-metrics.mjs [ledger-copy.sqlite] [--json]
2	// Reads a SQLite copy directly. Validation replays in memory; the source is never opened for writing.
3	import { DatabaseSync } from 'node:sqlite'
4	import { pathToFileURL } from 'node:url'
5	import { AgentTeamLedger } from '../packages/agent-team/src/ledger.ts'
6	import { agentTeamOperationSchema } from '../packages/agent-team/src/spec.ts'
7	import { reviewReminderRecipient } from '../packages/agent-team/src/task-reminders.ts'
8	
9	const HUMAN = 'member:human'
10	const DAY_MS = 86400000
11	const releaseKinds = new Set(['team/member-workspace-left', 'team/member-archived', 'team/member-removed', 'team/project-archived', 'team/project-owner-removed'])
12	const keyOf = marker => [marker.memberId, marker.taskRef, marker.kind, marker.baselineSequence].join('|')
13	const percent = (part, total) => total === 0 ? null : Math.round(part / total * 1000) / 10
14	const increment = (map, key, amount = 1) => map.set(key, (map.get(key) ?? 0) + amount)
15	
16	function readOperations(path) {
17	  const database = new DatabaseSync(path, { readOnly: true })
18	  try {
19	    return database.prepare('SELECT key, value FROM u_agent_team_operations').all()
20	      .map(row => [row.key, agentTeamOperationSchema.parse(JSON.parse(row.value))])
21	      .sort((left, right) => left[1].sequence - right[1].sequence)
22	  } finally { database.close() }
23	}
24	
25	function newState() {
26	  return { projects: new Map(), members: new Map(), owners: new Map(), tasks: new Map(), claims: new Map(),
27	    follows: new Map(), statusBaselines: new Map(), latestFacts: new Map(), reminders: new Map(), reminderEpisodes: new Map() }
28	}
29	
30	function apply(state, operation) {
31	  const data = operation.data
32	  if (operation.kind === 'team/project-created') {
33	    state.projects.set(data.project.projectRef, data.project)
34	    state.owners.set(data.project.projectRef, new Set())
35	  }
36	  if (operation.kind === 'team/project-archived') state.projects.set(data.project.projectRef, data.project)
37	  if (data.member !== undefined) state.members.set(data.member.memberId, data.member)
38	  if (operation.kind === 'team/project-owner-added') state.owners.get(data.projectRef)?.add(data.memberId)
39	  if (operation.kind === 'team/project-owner-removed') state.owners.get(data.projectRef)?.delete(data.memberId)
40	  if (releaseKinds.has(operation.kind) && data.member !== undefined) {
41	    for (const [projectRef, owners] of state.owners) {
42	      if (state.projects.get(projectRef)?.workspaceId === data.member.workspaceId) owners.delete(data.member.memberId)
43	    }
44	  }
45	  if (operation.kind === 'team/project-archived') state.owners.set(data.project.projectRef, new Set())
46	  if (operation.kind === 'team/thread-started') state.latestFacts.set(data.thread.threadRef, operation.sequence)
47	  if (operation.kind === 'team/thread-replied') state.latestFacts.set(data.thread.threadRef, operation.sequence)
48	  if (operation.kind === 'team/claim-created') state.claims.set(data.claim.claimRef, { ...data.claim, createdSequence: operation.sequence })
49	  if (operation.kind === 'team/claim-done' || operation.kind === 'team/claim-released') state.claims.set(data.claim.claimRef, { ...state.claims.get(data.claim.claimRef), ...data.claim })
50	  if (data.task !== undefined) {
51	    const previous = state.tasks.get(data.task.taskRef)
52	    state.tasks.set(data.task.taskRef, data.task)
53	    if (data.task.status === 'in_review' && previous?.status !== 'in_review') state.statusBaselines.set(data.task.taskRef, operation.sequence)
54	  }
55	  if (data.transfers !== undefined) for (const transfer of data.transfers) {
56	    const task = state.tasks.get(transfer.taskRef)
57	    if (task !== undefined) state.tasks.set(task.taskRef, { ...task, accountable: transfer.to })
58	  }
59	  if (data.inbox !== undefined) {
60	    for (const attention of data.inbox.attention.set) state.follows.set(`${attention.memberId}|${attention.threadRef}`, attention)
61	    for (const attention of data.inbox.attention.removed) state.follows.delete(`${attention.memberId}|${attention.threadRef}`)
62	  }
63	  if (operation.kind === 'team/reminder-raised') {
64	    const marker = data.inbox.reminderMarkers.added[0]
65	    state.reminders.set(keyOf(marker), { marker, operation, invalid: undefined })
66	    state.reminderEpisodes.set(`${data.taskRef}|${data.kind}|${data.recipient}|${data.baselineSequence}`, operation.sequence)
67	  }
68	}
69	
70	function liveReminder(state, marker) {
71	  const task = state.tasks.get(marker.taskRef)
72	  if (task === undefined || task.resolution !== 'open' || state.projects.get(task.projectRef)?.state !== 'active') return false
73	  if (marker.kind === 'review-backlog') {
74	    const recipient = reviewReminderRecipient(task,
75	      (projectRef, memberId) => memberId === HUMAN || state.owners.get(projectRef)?.has(memberId) === true,
76	      (taskRef, memberId) => [...state.claims.values()].some(claim => claim.taskRef === taskRef && claim.owner === memberId))
77	    return task.status === 'in_review' && state.statusBaselines.get(task.taskRef) === marker.baselineSequence && recipient === marker.memberId
78	  }
79	  return task.status === 'in_progress' && task.accountable === marker.memberId
80	    && (state.latestFacts.get(task.threadRef) ?? 0) <= marker.baselineSequence
81	    && (state.reminderEpisodes.get(`${marker.taskRef}|${marker.kind}|${marker.memberId}|${marker.baselineSequence}`) ?? marker.sequence) === marker.sequence
82	}
83	
84	function agentReplyMetric(state, operation, scope, message) {
85	  const parent = message.replyToMessageRef
86	  const recipients = new Set(operation.data.mentions ?? [])
87	  if (parent !== undefined) {
88	    const sender = parent === undefined ? undefined : state.messageSenders.get(parent)
89	    if (sender !== undefined && sender !== message.sender) recipients.add(sender)
90	  }
91	  return { scope, sequence: operation.sequence, occurredAt: operation.occurredAt,
92	    agentToAgent: message.sender !== HUMAN && [...recipients].some(memberId => memberId !== HUMAN) }
93	}
94	
95	export function calculateTrialMetrics(records) {
96	  const operations = [...records].sort((left, right) => left[1].sequence - right[1].sequence).map(([, operation]) => operation)
97	  const adoption = operations.find(operation => operation.kind === 'team/rules-version-adopted' && operation.data.version >= 2)
98	  const baselineSequence = adoption?.sequence ?? (operations.length > 0 ? operations[0].sequence : 0)
99	  const baselineMs = Date.parse(adoption?.occurredAt ?? operations[0]?.occurredAt ?? new Date(0).toISOString())
100	  const trialOperations = operations.filter(operation => operation.sequence >= baselineSequence)
101	  for (const operation of operations) {
102	    const inTrial = operation.sequence >= baselineSequence
103	  const state = newState()
104	  state.messageSenders = new Map()
105	  const replies = []
106	  const mainPostsByNonOwner = []
107	  const resolutions = []
108	  const immediate = new Map()
109	  const dailyByMember = new Map()
110	  const threshold = new Map()
111	  const dayFor = operation => Math.floor((Date.parse(operation.occurredAt) - baselineMs) / DAY_MS) + 1
112	  const notify = (memberId, operation, amount = 1) => {
113	    if (memberId === HUMAN || !state.members.has(memberId)) return
114	    increment(immediate, memberId, amount)
115	    if (dailyByMember.has(memberId)) increment(dailyByMember.get(memberId), dayFor(operation), amount)
116	  }
117	  for (const operation of trialOperations) {
118	    const data = operation.data
119	    const projectRef = data.projectRef ?? data.project?.projectRef ?? data.task?.projectRef ?? data.anchor?.projectRef ?? data.message?.projectRef
120	    const actor = operation.actor.kind === 'host' ? undefined : operation.actor.memberId
121	    const owners = projectRef === undefined ? new Set() : state.owners.get(projectRef) ?? new Set()
122	    if (inTrial && operation.kind === 'team/reminder-raised') {
123	      const marker = data.inbox.reminderMarkers.added[0]
124	      notify(marker.memberId, operation)
125	    } else if (inTrial && data.inbox !== undefined) {
126	      for (const marker of data.inbox.directMarkers.added) notify(marker.memberId, operation)
127	      for (const marker of data.inbox.activityMarkers.added) notify(marker.memberId, operation)
128	      for (const marker of data.inbox.mainMarkers?.added ?? []) notify(marker.memberId, operation)
129	      if (operation.kind === 'team/main-message-posted') {
130	        for (const memberId of owners) if (memberId !== actor) notify(memberId, operation)
131	      }
132	      if (operation.kind === 'team/thread-started' && data.kind === 'discussion') {
133	        for (const memberId of owners) if (memberId !== actor) notify(memberId, operation)
134	      }
135	      if (operation.kind === 'team/thread-replied') {
136	        for (const [key, attention] of state.follows) {
137	          const [memberId, threadRef] = key.split('|')
138	          if (threadRef !== data.thread.threadRef || memberId === actor) continue
139	          if (owners.has(memberId)) increment(threshold, memberId)
140	          else notify(memberId, operation)
141	        }
142	      }
143	    }
144	    if (inTrial && operation.kind === 'team/thread-replied') replies.push(agentReplyMetric(state, operation, 'thread', data.message))
145	    if (inTrial && operation.kind === 'team/main-message-posted') {
146	      replies.push(agentReplyMetric(state, operation, 'main', data.message))
147	      if (actor !== undefined && actor !== HUMAN && !owners.has(actor)) mainPostsByNonOwner.push(operation.sequence)
148	    }
149	    if (inTrial && operation.kind === 'team/task-changed' && (data.activity.kind === 'accept' || data.activity.kind === 'close')) {
150	      resolutions.push({ sequence: operation.sequence, occurredAt: operation.occurredAt, kind: data.activity.kind,
151	        byHuman: operation.actor.kind === 'human', taskRef: data.task.taskRef })
152	    }
153	    if (operation.kind === 'team/message-sent' || operation.kind === 'team/thread-replied' || operation.kind === 'team/thread-started') {
154	      const message = data.message ?? data.anchor
155	      state.messageSenders.set(message.messageRef, message.sender)
156	    }
157	    if (operation.kind === 'team/main-message-posted') state.messageSenders.set(data.message.messageRef, data.message.sender)
158	    for (const pending of state.reminders.values()) {
159	      if (pending.invalid === undefined && !liveReminder(state, pending.marker)) pending.invalid = { sequence: operation.sequence, occurredAt: operation.occurredAt }
160	    }
161	    for (const marker of data.inbox?.reminderMarkers?.removed ?? []) {
162	      const pending = state.reminders.get(keyOf(marker))
163	      if (pending !== undefined) pending.consumed = { sequence: operation.sequence, kind: operation.kind }
164	      state.reminders.delete(keyOf(marker))
165	    }
166	    if (inTrial && operation.kind === 'team/project-owner-added') dailyByMember.set(data.memberId, new Map())
167	    apply(state, operation)
168	  }
169	  const reminderOperations = trialOperations.filter(operation => operation.kind === 'team/reminder-raised')
170	  const historicalReminders = [...state.reminders.values()]
171	  const invalidBeforeRead = historicalReminders.filter(entry => entry.invalid !== undefined)
172	  const currentUnread = historicalReminders.filter(entry => entry.consumed === undefined)
173	  const lastSequence = trialOperations.at(-1)?.sequence ?? 0
174	  const lastMs = Date.parse(trialOperations.at(-1)?.occurredAt ?? new Date(baselineMs).toISOString())
175	  const elapsedDays = trialOperations.length === 0 ? 0 : Math.max(1, Math.floor((lastMs - baselineMs) / DAY_MS) + 1)
176	  const immediateFacts = Object.fromEntries([...immediate].sort())
177	  const ownerDaily = [...dailyByMember].flatMap(([memberId, byDay]) => [...byDay].map(([day, count]) => ({ day, memberId, immediateNotificationFacts: count })))
178	  const thresholdGroups = [...threshold].reduce((count, [, facts]) => count + Math.floor(facts / 5), 0)
179	  return {
180	    range: { baselineSequence, lastSequence, baselineOccurredAt: new Date(baselineMs).toISOString(),
181	      lastOccurredAt: new Date(lastMs).toISOString(), elapsedDays, completeDays: Math.max(0, Math.floor((lastMs - baselineMs) / DAY_MS)) },
182	    agentReplies: { total: replies.length, agentToAgent: replies.filter(reply => reply.agentToAgent).length,
183	      agentToAgentPercent: percent(replies.filter(reply => reply.agentToAgent).length, replies.length),
184	      byScope: Object.fromEntries(['thread', 'main'].map(scope => [scope, {
185	        total: replies.filter(reply => reply.scope === scope).length,
186	        agentToAgent: replies.filter(reply => reply.scope === scope && reply.agentToAgent).length }])) },
187	    resolutions: { total: resolutions.length, byHuman: resolutions.filter(entry => entry.byHuman).length,
188	      byHumanPercent: percent(resolutions.filter(entry => entry.byHuman).length, resolutions.length),
189	      acceptsByHuman: resolutions.filter(entry => entry.byHuman && entry.kind === 'accept').length,
190	      closesByHuman: resolutions.filter(entry => entry.byHuman && entry.kind === 'close').length },
191	    ownerDelivery: { immediateNotificationFactsByMember: immediateFacts,
192	      immediateNotificationFactsPerElapsedDayByMember: Object.fromEntries([...immediate].map(([memberId, count]) => [memberId, elapsedDays === 0 ? 0 : Math.round(count / elapsedDays * 100) / 100])),
193	      byDay: ownerDaily, ownerOrdinaryThreadFacts: Object.fromEntries([...threshold].sort()), thresholdGroupsOfFive: thresholdGroups },
194	    mainStream: { nonOwnerPosts: mainPostsByNonOwner.length },
195	    reminders: { raised: reminderOperations.length,
196	      byKind: Object.fromEntries(['review-backlog', 'stalled'].map(kind => [kind, reminderOperations.filter(operation => operation.data.kind === kind).length])),
197	      byRecipient: Object.fromEntries(reminderOperations.reduce((map, operation) => increment(map, operation.data.recipient), new Map())),
198	      unread: currentUnread.length, staleUnread: currentUnread.filter(entry => entry.invalid !== undefined).length,
199	      invalidatedBeforeConsumption: invalidBeforeRead.length,
200	      staleUnreadSamples: currentUnread.filter(entry => entry.invalid !== undefined).slice(0, 20).map(entry => ({
201	        ...entry.marker, reminderSequence: entry.operation.sequence, invalidAtSequence: entry.invalid.sequence })) },
202	    limitations: [
203	      'The ledger has no delivery-attempt or wake receipt. Immediate notification facts and threshold groups are not measured Agent interruptions.',
204	      'Thread ordinary delivery counts owners only; accountable non-owners and historical Attention changes need separate instrumentation for exact delivery totals.',
205	      'A reminder superseded before its marker was consumed is a review lead, not a confirmed false positive. Confirm false positives manually.',
206	    ],
207	  }
208	}
209	
210	function run(path) {
211	  const records = readOperations(path)
212	  const started = performance.now()
213	  const ledger = new AgentTeamLedger({ entries: () => records.entries() })
214	  ledger.validate()
215	  const result = calculateTrialMetrics(records)
216	  result.validation = { records: records.length, replayValidationMs: Math.round(performance.now() - started), result: 'passed' }
217	  if (process.argv.includes('--json')) console.log(JSON.stringify(result, null, 2))
218	  else {
219	    console.log(`账本副本 ${path}`)
220	    console.log(`重放校验：${result.validation.records} 条通过；统计范围 ${result.range.baselineSequence}–${result.range.lastSequence}；经过 ${result.range.elapsedDays} 个 UTC 自然日`)
221	    console.log(`Agent 回复：${result.agentReplies.total} 条，Agent 之间 ${result.agentReplies.agentToAgent} 条（${result.agentReplies.agentToAgentPercent ?? 'n/a'}%）`)
222	    console.log(`accept/close：${result.resolutions.total} 次，Human 执行 ${result.resolutions.byHuman} 次（${result.resolutions.byHumanPercent ?? 'n/a'}%）`)
223	    console.log(`非 owner 的 Main stream 发言：${result.mainStream.nonOwnerPosts} 条`)
224	    console.log(`提醒：${result.reminders.raised} 条；未读 ${result.reminders.unread} 条；已失效未读 ${result.reminders.staleUnread} 条；失效后才消费 ${result.reminders.invalidatedBeforeConsumption} 条`)
225	    console.log('owner 每个 UTC 日的 immediate 候选事实：')
226	    console.log(JSON.stringify(result.ownerDelivery.byDay, null, 2))
227	    console.log(`注意：${result.limitations.join('\n')}`)
228	    console.log('确认误报数：人工复查 staleUnreadSamples 与已消费提醒后另行记录，本脚本不自动判定。')
229	  }
230	}
231	
232	if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
233	  const path = process.argv.slice(2).find(argument => !argument.startsWith('--')) ?? `${process.env.DSH_HOME ?? `${process.env.HOME}/.dsh`}/storages/agent_team.sqlite`
234	  if (process.argv.includes('--help')) console.log('usage: node --import tsx scripts/team-trial-metrics.mjs [ledger-copy.sqlite] [--json]')
235	  else run(path)
236	}
